 * The alternation signature for ONE pair, or null. The walk goes newest
 * first and stops at a stable green (both members green on one build — the
 * episode ended). A build where exactly one member is red is a trade (the
 * partner green or not-yet-run counts as not-red). Both-red builds are
 * neutral: neither a trade nor a chain break.
 */
function detectAlternation(registry, keyA, keyB) {
    var runsA = tcRunRegistry.runsOf(registry, keyA);
    var runsB = tcRunRegistry.runsOf(registry, keyB);
    if (!runsA.length || !runsB.length) return null;
    var trades = [];
    var timeline = buildTimeline(runsA, runsB);
    for (var i = 0; i < timeline.length; i++) {
        var step = timeline[i];
        var aStatus = lastStatusAt(runsA, step.sha);
        var bStatus = lastStatusAt(runsB, step.sha);
        if (aStatus === 'green' && bStatus === 'green') break; // stable green — the episode ended
        if (aStatus === 'red' && bStatus !== 'red') {
            trades.push({ sha: step.sha, red: keyA });
        } else if (bStatus === 'red' && aStatus !== 'red') {
            trades.push({ sha: step.sha, red: keyB });
        }
    }
