    if (trades[0].red === trades[1].red) return null;
    var a = String(keyA) <= String(keyB) ? keyA : keyB;
    var b = a === keyA ? keyB : keyA;
    return {
        state: PAIR_STATE_CONFLICT,
        pairKey: pairKeyOf(keyA, keyB),
        a: a,
        b: b,
        holderNow: trades[0].red,
        holderPrev: trades[1].red,
        trades: trades
