        moveBugToDevelopmentQuietly(tracker, ticketKey, statuses);
    }
    reportRoutes(tracker, ticketKey, vars, bookkeeping.ledger, bookkeeping.registry, routes);
    if (!tcMaintenanceLedger.differentialRequests(vars.ledger).length) {
